package com.campus.lostfound.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="app_notifications") public class AppNotification { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private User recipient; @Column(nullable=false,length=500) private String message; @Column(nullable=false) private Instant createdAt=Instant.now(); private boolean read; protected AppNotification(){} public AppNotification(User u,String m){recipient=u;message=m;} public UUID getId(){return id;} public String getMessage(){return message;} public Instant getCreatedAt(){return createdAt;} public boolean isRead(){return read;} public void markRead(){read=true;} public User getRecipient(){return recipient;} }
